SELECT sys_role.id, sys_role.role_name, sys_role.role_code, sys_role.role_desc, sys_role.create_time, sys_role.update_time, sys_role.del_flag, sys_role.create_by, sys_role.update_by, sys_role.shop_id, sys_role.type FROM sys_role AS sys_role
AND sys_role.del_flag = '0' AND COALESCE(sys_role.type, '0') <> '2'
AND sys_role.role_name = #{query.roleName}
AND sys_role.role_code = #{query.roleCode}
AND sys_role.type = #{query.type}
AND sys_role.shop_id = #{query.shopId}
